/**
 * Coerce API boolean that may arrive as boolean | "true"/"false" | 0/1.
 * Missing/unknown → `whenMissing` (avoid truthy-string bugs like !"false").
 */
export function coerceApiBool(value: unknown, whenMissing = false): boolean {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0 && !Number.isNaN(value);
  if (typeof value === 'string') {
    const v = value.trim().toLowerCase();
    if (v === 'true' || v === '1' || v === 'yes') return true;
    if (v === 'false' || v === '0' || v === 'no' || v === '') return false;
  }
  if (value == null) return whenMissing;
  return Boolean(value);
}
